import sys

def main():
    s = sys.stdin.read().split()[0]
    N = 10 ** 6
    sieve = bytearray([1]) * (N + 1)
    sieve[0] = sieve[1] = 0
    for i in range(2, 1001):
        if sieve[i]:
            sieve[i * i::i] = bytes(len(range(i * i, N + 1, i)))
    n = len(s)
    INF = n + 1
    dp = [INF] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        best = INF
        for L in range(1, 7):
            j = i - L
            if j < 0:
                break
            if s[j] == '0':
                continue
            if sieve[int(s[j:i])] and dp[j] + 1 < best:
                best = dp[j] + 1
        dp[i] = best
    print(dp[n] if dp[n] < INF else -1)

main()

